u4f5c\\u533a\\u5e72\\u51c0,\\u65e0\\u4efb\\u4f55\\u53ef\\u7528\\u524d\\u7f6e\\u8d44\\u4ea7\\u3002\\u672c\\u65b9\\u6848\\u4e3a**\\u7eaf\\u8bbe\\u8ba1\\u6587\\u6863**,\\u4e0d\\u4f9d\\u8d56\\u6267\\u884c\\u3002\\n\\n---\\n\\n## 2) \\u62df\\u8ba2\\u7684\\u5b9e\\u9a8c\\u8bbe\\u8ba1\\u65b9\\u6cd5\\n\\n### 2.1 CycleNet \\u6a21\\u578b\\u67b6\\u6784\\u4e0e\\u5468\\u671f\\u5efa\\u6a21\\u673a\\u5236\\n\\nCycleNet \\u6838\\u5fc3\\u601d\\u60f3\\u662f\\u628a\\u65f6\\u95f4\\u5e8f\\u5217\\u663e\\u5f0f\\u62c6\\u4e3a**\\u53ef\\u5b66\\u4e60\\u7684\\u521d\\u59cb\\u5468\\u671f\\u5206\\u91cf `cycle`** \\u4e0e**\\u6b8b\\u5dee(\\u975e\\u5468\\u671f)\\u5206\\u91cf**,\\u628a\\\"\\u5468\\u671f\\\"\\u4f5c\\u4e3a\\u5f3a\\u5f52\\u7eb3\\u504f\\u7f6e\\u6ce8\\u5165\\u7f51\\u7edc\\u3002\\n\\n- **\\u8f93\\u5165\\u5f20\\u91cf** `X \\u2208 \\u211d^{B \\u00d7 L \\u00d7 C}`(\\u56de\\u770b\\u7a97\\u53e3 L,\\u901a\\u9053\\u6570 C)\\u3002\\n- **\\u521d\\u59cb\\u5468\\u671f\\u53c2\\u6570** `cycle \\u2208 \\u211d^{P \\u00d7 C}`(P=\\u5468\\u671f\\u957f\\u5ea6;**\\u5168\\u5c40\\u5171\\u4eab\\u3001\\u968f\\u8bad\\u7ec3\\u5b66\\u4e60**)\\u3002\\n- **\\u6b8b\\u5dee\\u5757\\u601d\\u8def(RCI)**: \\u65f6\\u523b t \\u7684\\u5468\\u671f\\u8d21\\u732e = `cycle[t mod P]`;\\u6b8b\\u5dee `R_in = X \\u2212 cycle_assigned`;\\u6d45\\u5c42\\u7f51\\u7edc(Linear/1D-Conv)\\u9884\\u6d4b\\u6b8b\\u5dee;\\u6700\\u7ec8\\u9884\\u6d4b `\\u0176 = cycle_assigned[:H] + R_pred`\\u3002\\n- **\\u53c2\\u6570\\u91cf**:10K\\u2013100K;CPU \\u53cb\\u597d\\u3002\\n- **\\u521d\\u59cb\\u5316\\u7b56\\u7565**:\\u4e09\\u4e2a\\u5019\\u9009 \\u2014\\n  - \\u96f6\\u521d\\u59cb\\u5316(\\u6700\\u7a33\\u5b9a,\\u6536\\u655b\\u6162)\\n  - \\u5c0f\\u9ad8\\u65af N(0, 0.02\\u00b2)(\\u9ed8\\u8ba4)\\n  - FFT \\u542f\\u53d1\\u5f0f(\\u7528\\u8bad\\u7ec3\\u96c6\\u6bcf\\u901a\\u9053\\u4e3b\\u9891\\u521d\\u59cb\\u5316,\\u5148\\u9a8c\\u5f3a\\u6570\\u636e\\u96c6)\\n- **\\u5468\\u671f\\u957f\\u5ea6 P**:\\u4e3b\\u5b9e\\u9a8c\\u4f5c\\u4e3a\\u8d85\\u53c2\\u6570\\u6309\\u6570\\u636e\\u96c6\\u5148\\u9a8c\\u786e\\u5b9a;\\u662f\\u5426\\\"\\u53ef\\u5fae P\\\"\\u7559\\u4f5c\\u6269\\u5c55\\u5bf9\\u6bd4\\u3002\\n\\n### 2.2 \\u6570\\u636e\\u96c6\\u5019\\u9009\\n\\n| \\u6570\\u636e\\u96c6 | \\u95f4\\u9694 | \\u901a\\u9053 | \\u4e3b\\u5468\\u671f P | \\u9009\\u7528\\u7406\\u7531 |\\n|---|---|---|---|---|\\n| ETTh1/h2 | 1h | 7 | 24 | \\u7ecf\\u5178\\u57fa\\u7ebf,\\u5468\\u671f\\u6e05\\u6670 |\\n| ETTm1/m2 | 15min | 7 | 96 | \\u5468\\u671f\\u66f4\\u77ed |\\n| Weather | 10min | 21 | 144 | \\u591a\\u901a\\u9053\\u6c14\\u8c61 |\\n| Traffic | 1h | 862 | 24 | \\u5927\\u901a\\u9053\\u6570\\u5178\\u578b |\\n| Exchange | 1d | 8 | 7+\\u2248250 | \\u5f31\\u5468\\u671f+\\u5f3a\\u8d8b\\u52bf,\\u9c81\\u68d2\\u6027\\u6d4b\\u8bd5 |\\n| Electricity | 1h | 321 | 24 | \\u4e0e Traffic \\u4e92\\u8865 |\\n| Solar-Energy | 10min | 137 | 144 | \\u53ef\\u9009 |\\n\\n**\\u9ed8\\u8ba4 6 \\u4ef6\\u5957**:ETTh1/h2\\u3001ETTm1/m2\\u3001Weather\\u3001Exchange\\u3001Electricity\\u3001Traffic\\u3002\\n\\n### 2.3 \\u5207\\u5206\\u4e0e\\u7a97\\u53e3\\n\\n- **L** \\u2208 {96, 336},**H** \\u2208 {96, 192, 336, 720}\\u3002\\n- **\\u5207\\u5206**:ETT-* 12/4/4 \\u6708(h) \\u6216 70/10/20(m);\\u5176\\u4f59 70/10/20 \\u65f6\\u95f4\\u987a\\u5e8f,**\\u7981\\u4e71\\u5e8f shuffle**\\u3002\\n- **\\u91c7\\u6837**:\\u8bad\\u7ec3\\u968f\\u673a\\u88c1\\u526a;val/test stride=1\\u3002\\n- **\\u6279\\u5927\\u5c0f**:32,L=336 \\u65f6\\u964d\\u5230 16\\u3002\\n\\n### 2.4 \\u5f52\\u4e00\\u5316\\u4e0e\\u7279\\u5f81\\n\\n- `StandardScaler` \\u6309\\u901a\\u9053\\u5728\\u8bad\\u7ec3\\u96c6\\u4e0a fit,\\u8f6c\\u6362 val/test\\u3002\\n- **\\u53bb\\u8d8b\\u52bf**:\\u4ec5 Exchange / Electricity \\u505a \\u2206\\u00b9 \\u5dee\\u5206\\u540e\\u9884\\u6d4b\\u8fd8\\u539f;\\u5176\\u4f59\\u4fdd\\u7559\\u539f\\u5c3a\\u5ea6\\u3002\\n- **\\u7f3a\\u5931**:\\u7ebf\\u6027\\u63d2\\u503c,>5% \\u7f3a\\u5931\\u901a\\u9053\\u5254\\u9664\\u3002\\n- **\\u4e0d\\u6ce8\\u5165 calendar \\u7279\\u5f81**,\\u8ba9 cycle \\u81ea\\u5b66;\\u4f5c\\u6d88\\u878d\\u53d8\\u91cf\\u3002\\n\\n### 2.5 \\u8bad\\u7ec3\\u7b56\\u7565\\n\\n| \\u9879 | \\u9ed8\\u8ba4 |\\n|---|---|\\n| \\u4f18\\u5316\\u5668 | Adam(\\u03b2=(0.9,0.999)) |\\n| \\u5b66\\u4e60\\u7387 | 1e-3(L=336 \\u7528 5e-4) |\\n| LR \\u8c03\\u5ea6 | OneCycleLR / Cosine / StepLR |\\n| \\u6279\\u5927\\u5c0f | 32(L=336 \\u7528 16) |\\n| Epochs | 10\\u201330,EarlyStop patience=3(val MSE) |\\n| \\u635f\\u5931 | MSE(\\u4e3b)\\u3001MAE(\\u8f85) |\\n| \\u6743\\u91cd\\u8870\\u51cf | 1e-4 |\\n| \\u968f\\u673a\\u79cd\\u5b50 | 3 \\u9897(0/1/2),\\u62a5\\u5747\\u503c\\u00b1std |\\n\\n### 2.6 \\u8bc4\\u4f30\\u6307\\u6807\\n\\n1. **MSE / MAE**(\\u6807\\u51c6\\u5316\\u5c3a\\u5ea6,\\u4e0e\\u6587\\u732e\\u5bf9\\u9f50)\\u3002\\n2. **MARE** = MSE/Var(x_test)\\u3002\\n3. **\\u5468\\u671f\\u5bf9\\u9f50\\u8bef\\u5dee**(\\u81ea\\u5b9a\\u4e49):\\u4ec5\\u5bf9\\\"\\u76f8\\u4f4d\\u76f8\\u540c\\u65f6\\u95f4\\u70b9\\\"\\u7edf\\u8ba1\\u9884\\u6d4b\\u8bef\\u5dee,\\u7528\\u4e8e\\u8bca\\u65ad\\u7eaf\\u5468\\u671f\\u5efa\\u6a21\\u80fd\\u529b\\u3002\\n4. **\\u76f8\\u4f4d\\u6f02\\u79fb\\u8bef\\u5dee**:\\u5728 \\u03b4\\u2208[0,P) \\u4e0a\\u627e\\u6700\\u4f18\\u6574\\u4f53\\u76f8\\u4f4d\\u504f\\u79fb;\\u663e\\u8457\\u975e 0 \\u65f6\\u8868\\u660e cycle \\u672a\\u5bf9\\u9f50\\u3002\\n\\n### 2.7 \\u5bf9\\u7167\\u57fa\\u7ebf\\n\\n| \\u57fa\\u7ebf | \\u7c7b\\u522b |\\n|---|---|\\n| Na\\u00efve Seasonal | \\u7edf\\u8ba1 |\\n| Last-value repeat | \\u7edf\\u8ba1 |\\n| Linear / DLinear | \\u6d45\\u5c42\\u7ebf\\u6027 |\\n| MLP(2 \\u5c42) | \\u6d45\\u5c42\\u975e\\u7ebf\\u6027 |\\n| N-HiTS / N-BEATS | \\u5757\\u72b6\\u53ef\\u89e3\\u91ca |\\n| **TimesNet** | \\u663e\\u5f0f\\u5468\\u671f(\\u4e3b\\u5bf9\\u7167) |\\n| **iTransformer** | Transformer \\u4e0a\\u754c |\\n\\n\\u4e3b\\u5bf9\\u7167\\u96c6\\u4e2d\\u5728 **Na\\u00efve / DLinear / MLP / TimesNet / iTransformer**\\u3002\\n\\n### 2.8 \\u7b97\\u529b\\u9884\\u7b97(CPU-only, 24 \\u6838)\\n\\n- CycleNet / DLinear / MLP / Na\\u00efve:\\u6bcf (dataset, window) 